const items = $input.all();
const pdfItems = [];
for (const item of items) {
  const bin = item.binary || {};
  const j = item.json || {};
  const emailSubject = j.subject || 'Email từ tuh@attech.com.vn';
  const senderEmail = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || j.from || 'tuh@attech.com.vn';

  // Lấy ngày nhận email thực tế từ header email (chuyển sang giờ Việt Nam UTC+7)
  let receivedDate = '';
  const rawDate = j.date || (j.headers && j.headers.date);
  if (rawDate) {
    try {
      const d = new Date(rawDate);
      if (!isNaN(d.getTime())) {
        const vnTime = new Date(d.getTime() + 7 * 60 * 60 * 1000);
        receivedDate = vnTime.toISOString().slice(0, 16).replace('T', ' ');
      }
    } catch (e) {}
  }
  if (!receivedDate && j.date) {
    receivedDate = String(j.date).slice(0, 16).replace('T', ' ');
  }

  for (const key of Object.keys(bin)) {
    const att = bin[key];
    const fileName = att.fileName || (att.fileExtension ? 'document.' + att.fileExtension : 'tai_lieu.pdf');
    const mime = (att.mimeType || '').toLowerCase();
    const isPdf = mime.includes('pdf') || fileName.toLowerCase().endsWith('.pdf');
    if (isPdf) {
      pdfItems.push({
        json: {
          hasPdf: true,
          emailSubject,
          senderEmail,
          receivedDate,
          pdfFileName: fileName,
          extractedTitle: fileName.replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim()
        },
        binary: {
          file: att
        }
      });
    }
  }
}
if (pdfItems.length === 0) {
  return [{ json: { hasPdf: false, items: [] } }];
}
return pdfItems;

const uploaded = $input.all();
const sourceItems = $('3. Lọc riêng các file PDF đính kèm').all();
const resultItems = uploaded.map((u, idx) => {
  const src = (sourceItems[idx] && sourceItems[idx].json) ? sourceItems[idx].json : {};
  return {
    emailSubject: src.emailSubject || u.json.name || 'Email đính kèm PDF',
    senderEmail: src.senderEmail || 'email@attech.com.vn',
    receivedDate: src.receivedDate || new Date().toISOString().slice(0, 16).replace('T', ' '),
    pdfFileName: u.json.name || src.pdfFileName || 'document.pdf',
    extractedTitle: src.extractedTitle || String(u.json.name || '').replace(/\.pdf$/i, ''),
    driveFileId: u.json.id || '',
    fileUrl: u.json.webViewLink || (u.json.id ? 'https://drive.google.com/file/d/' + u.json.id + '/view' : ''),
    driveFolderName: 'ATTECH_DOCUMENTS/03_TÀI LIỆU CHƯA XÁC THỰC'
  };
});
return [{ json: { success: true, count: resultItems.length, items: resultItems } }];

const res = $input.first().json;
const files = (res && Array.isArray(res.files)) ? res.files : [];
const pdfFiles = files.filter(f => {
  const name = (f.name || '').toLowerCase();
  return name.endsWith('.pdf') || (f.mimeType && f.mimeType.includes('pdf'));
});
const items = pdfFiles.map(f => {
  const cleanTitle = (f.name || '').replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim();
  return {
    driveFileId: f.id,
    pdfFileName: f.name,
    extractedTitle: cleanTitle,
    emailSubject: 'Tài liệu Drive: ' + f.name,
    senderEmail: 'tuh@attech.com.vn',
    receivedDate: '',
    fileUrl: f.webViewLink || ('https://drive.google.com/file/d/' + f.id + '/view'),
    driveFolderName: 'ATTECH_DOCUMENTS/03_TÀI LIỆU CHƯA XÁC THỰC',
    extractedIssuer: 'ATTECH',
    extractedCode: '',
    extractedIssueDate: f.createdTime ? String(f.createdTime).slice(0, 10) : '',
    scopeDomain: 'QL_KY_THUAT'
  };
});
return [{ json: { success: true, count: items.length, items: items } }];
